div.script:
// Note: In a real Splunk app, this form would POST to the FastAPI backend.
// Since this runs in Splunk's UI, you'd typically need a custom JS file or a proxy
// to send the data to the FastAPI server running on port 8080.
document.getElementById("feedbackForm").onsubmit = function(e) {
    e.preventDefault();
    const formData = new FormData(e.target);
    const data = {
        episode_id: formData.get("episode_id"),
        confirmed_technique_id: formData.get("confirmed_technique_id"),
        outcome_confirmed: formData.get("outcome_confirmed") === "true"
    };
    fetch("http://localhost:8080/api/v1/feedback", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data)
    })
    .then(r => r.json())
    .then(d => alert("Feedback saved!"))
    .catch(err => alert("Error: " + err));
};
